'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initial={done:[],notes:{},viewed:[],joints:[],snapshots:[],labels:[],runs:[],sequenceOK:false,directions:[],quiz:[],test:null,annotations:[]};
let state={...initial};try{const raw=JSON.parse(localStorage.getItem('actionlab-wushu-v2'));if(raw&&typeof raw==='object'){for(const k of Object.keys(initial)){if(Array.isArray(initial[k])&&Array.isArray(raw[k]))state[k]=raw[k];else if(k==='notes'&&raw.notes&&typeof raw.notes==='object')state.notes=raw.notes;else if(k==='sequenceOK'&&typeof raw[k]==='boolean')state[k]=raw[k];else if(k==='test'&&raw.test&&Number.isFinite(raw.test.threshold))state.test=raw.test}}}catch{}
let page=0,action=0,selectedJoint=13,showNames=false,showAngles=true,showTrail=false,playing=!matchMedia('(prefers-reduced-motion: reduce)').matches,phase=.46,speed=.5,reverse=false,lastFrame=0,lastDraw=0,sequence=[2,0,1],labelAnswered=false,annotImage=null,annotPoints=[],annotIndex=0,annotFile='',timerRemaining=1200,timerEnd=0,toastTimeout;
function save(){try{localStorage.setItem('actionlab-wushu-v2',JSON.stringify(state))}catch{toast('浏览器无法保存记录，请导出学习档案。')}updateNav()}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function updateNav(){$('#nav').innerHTML=`<a href="#overview" class="${page===0?'active':''}" ${page===0?'aria-current="page"':''}><span class="nav-num">◈</span><span>课程总览<small>THE LEARNING JOURNEY</small></span></a>`+lessons.map((l,i)=>`<a href="#lesson-${i+1}" class="${page===i+1?'active':''}" ${page===i+1?'aria-current="page"':''}><span class="nav-num">${state.done.includes(i)?'✓':String(i+1).padStart(2,'0')}</span><span>${l.name}<small>${l.short}</small></span></a>`).join('');$('#progressText').textContent=`${state.done.length} / 6`;$('#progress').value=state.done.length;if($('#completedCount'))$('#completedCount').textContent=state.done.length+' / 6';$('#breadcrumb').textContent=page?lessons[page-1].name:'课程总览'}
function go(n){location.hash=n?'lesson-'+n:'overview'}
function route(){const m=location.hash.match(/^#lesson-([1-6])$/);page=m?Number(m[1]):0;action=page===3?[0,2,1,0][Math.min(state.labels.length,3)]:0;reverse=false;phase=.5;labelAnswered=false;render();updateNav();window.scrollTo({top:0,behavior:'instant'})}
function markViewed(i){if(!state.viewed.includes(i)){state.viewed.push(i);save()}}
function selectAction(i){action=i;phase=.5;markViewed(i);document.querySelectorAll('[data-action]').forEach(b=>{b.classList.toggle('active',Number(b.dataset.action)===i);b.setAttribute('aria-pressed',Number(b.dataset.action)===i)});drawPose()}
function actionTabs(){return `<div class="pose-tabs">${poses.map((n,i)=>`<button class="pill ${action===i?'active':''}" data-action="${i}" aria-pressed="${action===i}" onclick="selectAction(${i})">${n}</button>`).join('')}</div>`}
function stage(mode=false){const compact=mode===true,still=mode==='sample';return `<div class="dark-stage"><div class="stage-head"><span>POSE ATELIER / 姿态实验台</span><b>● ${compact?'17 个点，读懂一招一式':'二维合成骨架 · 教学示意'}</b></div><svg id="pose" class="pose-svg" viewBox="0 0 600 400" role="img" aria-label="武术人体关键点骨架，左右肢体以青绿和金色区分"></svg><div class="stage-foot"><div class="legend"><span><i></i>人体左侧</span><span class="right"><i></i>人体右侧</span></div><span id="stagePhase">定势 / KEYFRAME</span></div></div>${compact||still?'':`<div class="controls"><button id="playButton" aria-pressed="${playing}" onclick="togglePlay()">${playing?'Ⅱ 暂停':'▷ 播放'}</button><button id="namesButton" class="${showNames?'active':''}" aria-pressed="${showNames}" onclick="toggleLayer('names')">关节名称</button><button id="anglesButton" class="${showAngles?'active':''}" aria-pressed="${showAngles}" onclick="toggleLayer('angles')">关节角度</button><button id="trailButton" class="${showTrail?'active':''}" aria-pressed="${showTrail}" onclick="toggleLayer('trail')">手腕轨迹</button><select aria-label="播放速度" onchange="speed=Number(this.value)"><option value="0.5" ${speed===.5?'selected':''}>0.5× 慢放</option><option value="1" ${speed===1?'selected':''}>1× 播放</option></select></div><div class="timeline"><span>起势</span><input id="timeline" aria-label="动作时间轴" type="range" min="0" max="100" value="${phase*100}" oninput="scrub(this.value)"><span>收势</span><span id="frameValue">50%</span></div>`}`}
function overview(){let next=lessons.findIndex((_,i)=>!state.done.includes(i));if(next<0)next=0;return `<section class="hero"><div><span class="eyebrow">THE ART OF MOTION · 武术与智能</span><h1>以骨观形，<br><em>以数识势。</em></h1><p>当一招一式遇见人工智能。<br>从观察身体，到描绘关键点，再亲手搭建动作识别规则。<br>六次实践，让机器眼中的武术变得清晰。</p><div class="hero-actions"><button class="primary" onclick="go(${next+1})">${state.done.length?'继续学习':'开启学习之旅'} <span style="margin-left:15px">↗</span></button><button class="secondary" onclick="go(2)">探索关键点实验台</button></div><div class="hero-stats"><div><b>06</b><span>课时</span><small>循序渐进的学习旅程</small></div><div><b>45</b><span>分钟 / 课</span><small>每节课都有动手实践</small></div><div><b>17</b><span>关键点</span><small>描绘人体的动作语言</small></div></div></div><div class="hero-art">${stage(true)}<div class="art-caption"><span>弓步冲拳 · 从动作到数据</span><span>FIG. 01 / SYNTHETIC POSE</span></div></div></section><section><div class="section-title"><h2>六课入门，一路实践<small>YOUR LEARNING PATH</small></h2><span>每课 45 分钟 · 建议每周 1–2 课</span></div><div class="course-grid">${lessons.map((l,i)=>`<a class="course-card ${i===1?'featured':''}" href="#lesson-${i+1}"><div class="card-top"><b>${String(i+1).padStart(2,'0')}</b><span>${state.done.includes(i)?'✓ 已完成':i===1?'核心课时 · 45 MIN':'实践课 · 45 MIN'}</span></div><h3>${l.name}</h3><div class="question">${l.question}</div><p>${l.intro}</p><div class="card-bottom"><span>课堂产出 / ${l.output}</span><b>↗</b></div></a>`).join('')}</div><div class="curriculum-note"><h3>学会识别，也学会质疑。</h3><p>每节课沿着「观察 → 动手 → 解释 → 验证」展开。没有编程基础也可以开始；进阶学生可导出关键点 JSON，继续在 Python 中探索。教学骨架与合成数据用于理解原理，不等同于真实视觉模型。</p></div></section>`}
function lessonHeader(i){const l=lessons[i];return `<section class="lesson-title"><div><span class="eyebrow">LESSON ${String(i+1).padStart(2,'0')} / ${l.en}</span><h1>${l.name}——${l.question}</h1><p>${l.intro}</p></div><div class="lesson-badge">45<small>MINUTES / 课时</small></div></section><div class="schedule" aria-label="45分钟教学安排">${duration.map((d,j)=>`<div title="${l.phases[j]}"><b>${phaseNames[j]} · ${d}′</b><span>${l.phases[j]}</span></div>`).join('')}</div>`}
function jointPanel(){return `<div class="panel-label">INSPECT A KEYPOINT / 点选关节</div><h2 class="task-heading">每一个点，<br>都是身体的坐标。</h2><label class="field-label" for="jointSelect">选择关节（按人物自身左右）</label><select id="jointSelect" class="joint-select" onchange="selectJoint(Number(this.value))">${jointNames.map((n,i)=>`<option value="${i}" ${selectedJoint===i?'selected':''}>${String(i).padStart(2,'0')} · ${n}</option>`).join('')}</select><div id="jointInfo" class="joint-info"></div><div class="fields"><div class="metric"><span>左膝内角 · 髋—膝—踝</span><b id="kneeMetric">—</b><small>随当前帧实时计算</small></div><div class="metric"><span>双踝高度差 / 躯干长度</span><b id="heightMetric">—</b><small>不随画面整体缩放变化</small></div></div><div class="notice">坐标以画布左上角为原点，x 向右、y 向下，均归一化至 0–1。青绿为人物左侧，金色为右侧。角度是二维投影内角。</div><button class="primary" onclick="snapshot()">＋ 保存当前关键点快照</button><div id="snapshotStatus" class="feedback">已查看 ${state.joints.length} / 17 个关节 · ${state.snapshots.length} 份快照</div>`}
function observation(){return `<div class="lab-layout"><div><div class="panel">${stage()}</div>${actionTabs()}<p class="light-label">三种招式为教学简化示意。跟练请保持间距，缓慢完成，无需发力。</p></div><div class="panel panel-pad"><div class="panel-label">LOOK CLOSER / 观察挑战</div><h2 class="task-heading">不看衣着和表情，<br>你还认得这招吗？</h2><p class="lab-copy">先比较手腕与肩的位置，再比较髋、膝、踝。把一句“这像提膝”变成能够验证的描述。</p><ol class="task-list"><li><b>弓步冲拳</b><br>观察一侧手臂伸出与两腿支撑。</li><li><b>马步架掌</b><br>观察两膝同时弯曲与上肢位置。</li><li><b>提膝亮掌</b><br>观察一侧脚踝抬高与支撑腿。</li></ol><div class="notice">静止的一帧描述“姿态”；前后帧的变化帮助描述“动作”。用第二课的关键点，可以把观察变成数据。</div></div></div>`}
function keypoints(){return `<div class="lab-layout"><div><div class="panel">${stage()}</div>${actionTabs()}</div><div class="panel panel-pad">${jointPanel()}</div></div>${annotationPanel()}`}
function annotationPanel(){return `<section class="panel panel-pad" style="margin-top:20px"><div class="panel-title"><h3>描点工作台 · 把自己的图片变成骨架</h3><small>可选实践 / 本地处理</small></div><p class="lab-copy">上传一张完整单人动作图，按人物自身左右标出关节。看不见的点选择“标为不可见”；完成 17 项后可保存与导出，原图不会上传或存入学习档案。</p><div class="upload-row"><label for="imageUpload">选择图片</label><input type="file" id="imageUpload" accept="image/png,image/jpeg,image/webp" onchange="loadImage(this.files[0])"><span id="annotationStatus">${annotImage?'继续当前图片标注':'支持 JPG / PNG / WebP，最大 10 MB'}</span></div><div id="annotationArea">${annotImage?'':'<div class="annotation-placeholder">上传后点击图片，为鼻尖、肩、肘、腕、髋、膝、踝逐一标点。<br>尚无图片？上方的合成骨架也可以完成本课核心实验。</div>'}</div><div class="work-actions"><button onclick="skipPoint()">标为不可见</button><button onclick="undoPoint()">撤销上一个点</button><button onclick="saveAnnotation()" class="primary">保存并导出标注 JSON</button></div><div class="feedback" id="annotationFeedback" aria-live="polite"></div></section>`}
function labeling(){let n=state.labels.length;return `<div class="lab-layout"><div class="panel">${stage('sample')}</div><div class="panel panel-pad"><div class="panel-label">LABEL THE POSE / 数据标注</div><h2 class="task-heading">${n<4?'样本 '+(n+1)+' / 4':'标注集已完成'}</h2>${n<4?`<p class="lab-copy">依据可见骨架判断姿态。证据不足时，请保留“不确定”，不要猜测缺失的关节。</p><div class="options">${[...poses,'无法判断'].map((n,i)=>`<button onclick="labelSample(${i})">${String.fromCharCode(65+i)}　${n}</button>`).join('')}</div><div class="feedback" id="labelFeedback" aria-live="polite"></div><button id="nextSample" hidden onclick="nextSample()">下一个样本 →</button>`:state.labels.map((x,i)=>`<div class="sample-row"><span>样本 ${i+1} · ${esc([...poses,'无法判断'][x.answer])}</span><span>${x.correct?'✓ 正确':'参考：'+[...poses,'无法判断'][x.truth]}</span></div>`).join('')+`<div class="notice">样本 4 缺失双臂与下肢，无法可靠区分三种动作。诚实地标记未知，是高质量数据的一部分。</div><button onclick="exportDataset()">↓ 导出标注数据集</button>`}</div></div>${annotationPanel()}`}
function ruleLab(){return `<div class="lab-layout"><div><div class="panel">${stage()}</div>${actionTabs()}</div><div class="panel panel-pad"><div class="panel-label">FEATURE LAB / 从点到特征</div><h2 class="task-heading">一条规则，<br>能读懂提膝吗？</h2><p class="lab-copy">h = |左踝 y − 右踝 y| ÷ 躯干长度<br>如果 h ≥ 阈值，预测为“提膝”。躯干长度取肩部中点到髋部中点的距离。</p><div class="fields"><div class="metric"><span>当前左膝内角</span><b id="kneeMetric">—</b></div><div class="metric"><span>当前画面 h</span><b id="heightMetric">—</b></div></div><div class="split-line"></div><label for="threshold" class="field-label">高度差阈值 <b id="thresholdValue">${lastThreshold().toFixed(2)}</b></label><input id="threshold" type="range" min="0.1" max="0.9" step="0.05" value="${lastThreshold()}" oninput="$('#thresholdValue').textContent=Number(this.value).toFixed(2)"><div class="work-actions"><button class="primary" onclick="runRule()">运行验证 · 8 个样本</button></div><div id="ruleResult" class="feedback" aria-live="polite">至少比较两组阈值，观察误报与漏报。</div><div id="runHistory" class="history">${historyHTML()}</div></div></div><div class="panel panel-pad" style="margin-top:20px"><div class="panel-title"><h3>验证集 · 合成特征样本</h3><small>用于调参，不是独立测试集</small></div><div class="fields">${validationSamples.map(x=>`<div class="sample-row"><span>${x.name}</span><span>h = ${x.value.toFixed(2)} · ${x.truth?'提膝':'非提膝'}</span></div>`).join('')}</div><div class="notice">低提膝可能被漏判，跨步可能被误判。此规则只演示二分类；没有训练模型。关节角度也受拍摄视角影响，不能作为武术规范的评分依据。</div></div>`}
function sequenceLab(){return `<div class="lab-layout"><div class="panel">${stage()}<div class="controls"><button onclick="playDirection(false)" id="forwardButton" class="${reverse?'':'active'}">▷ 正放 · 观察出拳</button><button onclick="playDirection(true)" id="reverseButton" class="${reverse?'active':''}">◁ 倒放 · 观察收拳</button></div></div><div class="panel panel-pad"><div class="panel-label">TIME TELLS MORE / 连续观察</div><h2 class="task-heading">同一张定格，<br>可能是不同的动作。</h2><p class="lab-copy">前半段：手腕逐渐远离肩膀；后半段：手腕逐渐靠近肩膀。只看中间一帧，无法知道它朝哪个方向运动。</p><div class="fields"><div class="metric"><span>左腕到左肩 / 躯干长度</span><b id="wristMetric">—</b></div><div class="metric"><span>当前阶段</span><b id="motionMetric" style="font:17px var(--serif)">—</b></div></div><div class="notice">轨迹颜色只标身体左右，不代表置信度。要判断动作，还需要前后帧的方向、持续时间与可靠的关键点。</div><button onclick="showTrail=true;drawPose();document.querySelector('#trailButton')?.classList.add('active')">查看手腕运动轨迹 ↗</button></div></div><div class="panel panel-pad" style="margin-top:20px"><h3>把三帧排成一次出拳</h3><p class="lab-copy">把距离由近到远的阶段排列起来。数字是手腕到肩膀的归一化距离。</p><div id="sequenceCards"></div><button class="primary" onclick="checkSequence()">验证动作顺序</button><div class="feedback" id="sequenceFeedback" aria-live="polite">${state.sequenceOK?'✓ 已完成一次正确排序。':''}</div></div>`}
function finalLab(){return `<div class="report-grid"><div class="metric"><span>完成课时</span><b id="completedCount">${state.done.length} / 6</b></div><div class="metric"><span>标注样本</span><b>${state.labels.length} / 4</b></div><div class="metric"><span>验证实验</span><b>${state.runs.length} 次</b></div></div><div class="lab-layout"><div class="panel panel-pad"><div class="panel-label">UNSEEN TEST / 独立检验</div><h2 class="task-heading">用新样本，回答旧问题。</h2><p class="lab-copy">使用第四课最后一组阈值进行独立测试。首次运行后锁定本次阈值；看到测试结果后再次改进，应使用新的测试数据。</p><div class="metric"><span>${state.test?'本次测试已锁定阈值':'待测试阈值（取自最后一次验证）'}</span><b>${(state.test?.threshold??lastThreshold()).toFixed(2)}</b></div><div class="work-actions"><button class="primary" onclick="runTest()" ${state.test?'disabled':''}>${state.test?'已完成独立测试':'运行独立测试 · 6 个新样本'}</button><button onclick="go(4)">回到规则实验</button></div><div id="testResult" class="feedback" aria-live="polite">${state.test?resultHTML(state.test):'先在第四课完成验证实验，再测试。'}</div><div class="notice">此结果来自独立的合成小样本，仅检验课堂规则。真实应用仍需真实数据、多视角与更多参与者的验证。</div></div><div class="panel panel-pad"><div class="panel-label">TRANSFER YOUR LEARNING / 迁移挑战</div>${quizzes.map((q,i)=>`<div class="quiz-block"><h3><label for="quiz${i}">${i+1}. ${q.q}</label></h3><select id="quiz${i}" onchange="state.quiz[${i}]=Number(this.value);save()"><option value="-1">请选择你的判断</option>${q.a.map((a,j)=>`<option value="${j}" ${state.quiz[i]===j?'selected':''}>${a}</option>`).join('')}</select></div>`).join('')}<button onclick="gradeQuiz()">检查我的理解</button><div id="quizFeedback" class="feedback" aria-live="polite"></div></div></div>`}
function notebook(i){const l=lessons[i];return `<div class="below-grid"><section class="panel panel-pad"><div class="panel-label">LEARNING NOTE / 课堂产出</div><h3>${l.output}</h3><label class="field-label" for="lessonNote">${l.prompt}</label><textarea id="lessonNote" placeholder="用本节课的操作结果和观察证据回答……（至少 20 字）" oninput="state.notes[${i}]=this.value;save()">${esc(state.notes[i]||'')}</textarea><div class="work-actions"><button class="primary" onclick="completeLesson(${i})">提交本课成果 ✓</button><button onclick="downloadReport()">↓ 导出档案</button></div><div id="completionFeedback" class="feedback" aria-live="polite">${state.done.includes(i)?'✓ 本课已完成，内容可继续完善。':'验收：'+l.criteria}</div></section><section class="panel panel-pad"><div class="panel-label">IN THE CLASSROOM / 20 分钟动手实践</div><h3>小组操作清单</h3><ol class="task-list">${l.tasks.map(t=>`<li>${t}</li>`).join('')}</ol><div class="timer"><b id="timerClock">${formatTime(timerRemaining)}</b><button id="timerButton" onclick="toggleTimer()">${timerEnd?'暂停计时':'开始实践计时'}</button><button onclick="resetTimer()">重置</button></div><div class="notice">离堂问题 / ${l.exit}</div></section></div><div class="lesson-nav"><button onclick="go(${i===0?0:i})">← ${i===0?'课程总览':'上一课'}</button><span>第 ${i+1} 课 / 共 6 课</span><button onclick="go(${i===5?0:i+2})">${i===5?'返回课程总览':'下一课'} →</button></div>`}
function render(){if(page===0){$('#content').innerHTML=overview()}else{const i=page-1;$('#content').innerHTML=lessonHeader(i)+[observation,keypoints,labeling,ruleLab,sequenceLab,finalLab][i]()+notebook(i);if(page===1)markViewed(0);if(page===5)renderSequence();if(annotImage&&(page===2||page===3))mountAnnotation()}drawPose()}
function togglePlay(){playing=!playing;syncPlay()}
function syncPlay(){const b=$('#playButton');if(b){b.textContent=playing?'Ⅱ 暂停':'▷ 播放';b.setAttribute('aria-pressed',playing)}}
function scrub(v){phase=Number(v)/100;playing=false;syncPlay();drawPose()}
function toggleLayer(layer){if(layer==='names')showNames=!showNames;if(layer==='angles')showAngles=!showAngles;if(layer==='trail')showTrail=!showTrail;const v=layer==='names'?showNames:layer==='angles'?showAngles:showTrail;const b=$('#'+layer+'Button');b.classList.toggle('active',v);b.setAttribute('aria-pressed',v);drawPose()}
function selectJoint(i){selectedJoint=i;if(!state.joints.includes(i)){state.joints.push(i);save()}if($('#jointSelect'))$('#jointSelect').value=i;drawPose();if($('#snapshotStatus'))$('#snapshotStatus').textContent=`已查看 ${state.joints.length} / 17 个关节 · ${state.snapshots.length} 份快照`}
const rest=[[300,88],[307,83],[293,83],[316,89],[284,89],[330,125],[270,125],[351,166],[249,166],[350,135],[263,192],[321,216],[279,216],[333,275],[267,275],[345,331],[255,331]];
const targets=[[[310,88],[317,83],[303,83],[326,89],[294,89],[342,128],[283,128],[398,129],[260,163],[458,130],[291,181],[327,216],[285,216],[382,266],[233,264],[386,331],[175,331]],[[300,112],[307,107],[293,107],[316,113],[284,113],[335,147],[265,147],[378,113],[223,177],[349,70],[192,147],[325,236],[275,236],[383,263],[217,263],[389,331],[211,331]],[[298,79],[305,74],[291,74],[314,80],[282,80],[330,116],[270,116],[369,80],[237,156],[344,48],[269,171],[321,207],[279,207],[374,205],[277,270],[348,255],[279,331]]];
function getPose(a=action,p=phase){const weight=Math.sin(Math.PI*Math.max(0,Math.min(1,p)));return rest.map((r,i)=>r.map((v,j)=>v+(targets[a][i][j]-v)*weight))}
