const focused=document.activeElement?.dataset?.joint;svg.innerHTML=s;if(focused!==undefined)svg.querySelector(`[data-joint="${focused}"]`)?.focus({preventScroll:true});svg.setAttribute('aria-label',(page===3?'待标注样本':poses[action])+'的17点二维教学骨架');
if($('#stagePhase'))$('#stagePhase').textContent=page===3?'样本 '+Math.min(state.labels.length+1,4)+' / SYNTHETIC':`${phase<.45?'起势 → 定势':phase>.55?'定势 → 收势':'定势'} / ${String(Math.round(phase*100)).padStart(2,'0')}%`;
